// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/api/v1/access/capabilities", wrapper.GetAccessCapabilities)
	router.GET(options.BaseURL+"/api/v1/access/users", wrapper.ListAccessUsers)
	router.POST(options.BaseURL+"/api/v1/access/users", wrapper.CreateAccessUser)
	router.GET(options.BaseURL+"/api/v1/access/snapshot", wrapper.GetAccessManagementSnapshot)
	router.GET(options.BaseURL+"/api/v1/access/groups", wrapper.ListAccessGroups)
	router.POST(options.BaseURL+"/api/v1/access/groups", wrapper.CreateAccessGroup)
	router.POST(options.BaseURL+"/api/v1/access/groups/:groupId/disable", wrapper.DisableAccessGroup)
	router.POST(options.BaseURL+"/api/v1/access/groups/:groupId/memberships", wrapper.CreateAccessMembership)
	router.GET(options.BaseURL+"/api/v1/access/groups/:groupId/membership-candidates", wrapper.ListAccessMembershipCandidates)
	router.GET(options.BaseURL+"/api/v1/access/scopes/:scopeKind/:scopeId/options", wrapper.GetAccessScopeOptions)
	router.GET(options.BaseURL+"/api/v1/access/roles", wrapper.ListAccessRoles)
	router.POST(options.BaseURL+"/api/v1/access/roles", wrapper.CreateAccessRole)
	router.GET(options.BaseURL+"/api/v1/access/bindings", wrapper.ListAccessBindings)
	router.POST(options.BaseURL+"/api/v1/access/bindings", wrapper.CreateAccessBinding)
	router.GET(options.BaseURL+"/api/v1/access/denies", wrapper.ListAccessDenies)
	router.POST(options.BaseURL+"/api/v1/access/denies", wrapper.CreateAccessDeny)
	router.POST(options.BaseURL+"/api/v1/access/users/:userId/disable", wrapper.DisableAccessUser)
	router.POST(options.BaseURL+"/api/v1/access/memberships/:membershipId/revoke", wrapper.RevokeAccessMembership)
	router.GET(options.BaseURL+"/api/v1/access/memberships", wrapper.ListAccessMemberships)
	router.POST(options.BaseURL+"/api/v1/access/roles/:roleId/disable", wrapper.DisableAccessRole)
	router.POST(options.BaseURL+"/api/v1/access/bindings/:bindingId/revoke", wrapper.RevokeAccessBinding)
	router.POST(options.BaseURL+"/api/v1/access/denies/:denyId/revoke", wrapper.RevokeAccessDeny)
	router.GET(options.BaseURL+"/api/v1/argocd/candidates", wrapper.ListArgoCDCandidates)
	router.GET(options.BaseURL+"/api/v1/argocd/candidate-assignment-scopes", wrapper.ListArgoCDCandidateAssignmentScopes)
	router.POST(options.BaseURL+"/api/v1/argocd/candidates/:candidateId/assignment", wrapper.AssignArgoCDCandidate)
	router.GET(options.BaseURL+"/api/v1/catalog/visible-applications", wrapper.ListVisibleCatalogApplications)
	router.GET(options.BaseURL+"/api/v1/catalog/resource-tree", wrapper.GetCatalogResourceTree)
	router.POST(options.BaseURL+"/api/v1/catalog/organizations", wrapper.CreateCatalogOrganization)
	router.DELETE(options.BaseURL+"/api/v1/catalog/organizations/:organizationId", wrapper.DeleteCatalogOrganization)
	router.PATCH(options.BaseURL+"/api/v1/catalog/organizations/:organizationId", wrapper.UpdateCatalogOrganization)
	router.POST(options.BaseURL+"/api/v1/catalog/organizations/:organizationId/projects", wrapper.CreateCatalogProject)
	router.POST(options.BaseURL+"/api/v1/catalog/organizations/:organizationId/projects/:projectId/environments", wrapper.CreateCatalogEnvironment)
	router.POST(options.BaseURL+"/api/v1/catalog/organizations/:organizationId/projects/:projectId/environment-label-mappings", wrapper.CreateCatalogEnvironmentLabelMapping)
	router.GET(options.BaseURL+"/api/v1/catalog/applications", wrapper.ListCatalogApplications)
	router.GET(options.BaseURL+"/api/v1/catalog/applications/:applicationId", wrapper.GetCatalogApplication)
	router.GET(options.BaseURL+"/api/v1/catalog/applications/:applicationId/status", wrapper.GetCatalogApplicationStatus)
	router.POST(options.BaseURL+"/api/v1/catalog/applications/:applicationId/onboarding/dry-run", wrapper.DryRunApplicationOnboarding)
	router.POST(options.BaseURL+"/api/v1/catalog/applications/:applicationId/onboarding/confirm", wrapper.ConfirmApplicationOnboarding)
	router.GET(options.BaseURL+"/api/v1/deployment-requests", wrapper.ListDeploymentRequests)
	router.GET(options.BaseURL+"/api/v1/deployment-requests/:requestId", wrapper.GetDeploymentRequest)
	router.PATCH(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId", wrapper.UpdateDeploymentRequestVersionMetadata)
	router.POST(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId/reviews/:reviewTaskId/decisions", wrapper.DecideDeploymentReview)
	router.POST(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId/reviews/:reviewTaskId/reassignments", wrapper.ReassignDeploymentReview)
	router.POST(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId/transitions", wrapper.TransitionDeploymentRequest)
	router.POST(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId/retry", wrapper.RetryDeploymentRequest)
	router.POST(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId/terminate", wrapper.TerminateDeploymentRequest)
	router.POST(options.BaseURL+"/api/v1/deployment-requests/:requestId/versions/:requestVersionId/unlock", wrapper.UnlockDeploymentRequest)
	router.GET(options.BaseURL+"/api/v1/release-workflows", wrapper.ListReleaseWorkflows)
	router.POST(options.BaseURL+"/api/v1/release-workflows", wrapper.CreateReleaseWorkflow)
	router.GET(options.BaseURL+"/api/v1/release-workflows/review-options", wrapper.GetReleaseWorkflowReviewOptions)
	router.DELETE(options.BaseURL+"/api/v1/release-workflows/:workflowId", wrapper.DeleteReleaseWorkflow)
	router.POST(options.BaseURL+"/api/v1/release-workflows/:workflowId/versions", wrapper.CreateReleaseWorkflowVersion)
	router.POST(options.BaseURL+"/api/v1/release-workflows/:workflowId/versions/:workflowVersionId/lifecycle", wrapper.ChangeReleaseWorkflowVersionLifecycle)
	router.GET(options.BaseURL+"/api/v1/deployment-plans", wrapper.ListDeploymentPlans)
	router.POST(options.BaseURL+"/api/v1/deployment-plans", wrapper.CreateDeploymentPlan)
	router.POST(options.BaseURL+"/api/v1/deployment-plans/:planId/versions", wrapper.CreateDeploymentPlanVersion)
	router.POST(options.BaseURL+"/api/v1/deployment-plans/:planId/versions/:planVersionId/lifecycle", wrapper.ChangeDeploymentPlanVersionLifecycle)
	router.GET(options.BaseURL+"/api/v1/deployment-bindings", wrapper.GetDeploymentBinding)
	router.POST(options.BaseURL+"/api/v1/deployment-bindings", wrapper.BindDeploymentDefinitions)
	router.GET(options.BaseURL+"/api/v1/deployment-executions/:executionId", wrapper.GetDeploymentExecution)
	router.GET(options.BaseURL+"/api/v1/deployment-history", wrapper.ListDeploymentHistory)
	router.GET(options.BaseURL+"/api/v1/notifications", wrapper.ListNotifications)
	router.POST(options.BaseURL+"/api/v1/notifications/:notificationId/read", wrapper.MarkNotificationRead)
	router.POST(options.BaseURL+"/api/v1/notifications/read-all", wrapper.MarkAllNotificationsRead)
	router.GET(options.BaseURL+"/api/v1/notifications/events", wrapper.StreamNotificationEvents)
	router.GET(options.BaseURL+"/api/v1/auth/login", wrapper.BeginAuthLogin)
	router.GET(options.BaseURL+"/api/v1/auth/callback", wrapper.CompleteAuthCallback)
	router.POST(options.BaseURL+"/api/v1/auth/local/login", wrapper.LoginLocal)
	router.POST(options.BaseURL+"/api/v1/auth/password", wrapper.ChangeLocalPassword)
	router.GET(options.BaseURL+"/api/v1/auth/session", wrapper.GetAuthSession)
	router.POST(options.BaseURL+"/api/v1/auth/logout", wrapper.LogoutAuthSession)
	router.POST(options.BaseURL+"/api/v1/auth/backchannel-logout", wrapper.BackchannelLogout)
	router.GET(options.BaseURL+"/api/v1/system/status", wrapper.GetSystemStatus)
}

